#!/bin/bash
# bootstrap خادم مختبر التصدّي السيبراني — يُشغَّل على الخادم (root). لا يحوي أسراراً.
set -u
LOG(){ echo "[$(date '+%F %T')] $*"; }
RAW="https://raw.githubusercontent.com/alhakami54321/cyber-lab/main/server"
export DEBIAN_FRONTEND=noninteractive
LOG "=== boot start ==="
apt-get update -qq || LOG "WARN apt update"
apt-get install -y -qq ttyd nginx tmux nmap python3 iproute2 curl iptables >/dev/null 2>&1 || LOG "WARN apt install"
for b in ttyd nginx tmux nmap; do command -v $b >/dev/null || { LOG "MISSING $b"; }; done

# مفتاح الوصول — يُولَّد هنا، لا يُخزَّن في المستودع
AF=/root/.lab_access
[ -s $AF ] || head -c16 /dev/urandom | base64 | tr -dc 'a-zA-Z0-9' | head -c20 > $AF
ACCESS=$(cat $AF)
IP=$(curl -s --max-time 10 https://api.ipify.org || hostname -I | awk '{print $1}')
DOMAIN=$(echo "$IP" | tr "." "-").sslip.io

# الهدف الوهمي 10.10.10.5
mkdir -p /opt/lab
cat > /opt/lab/fake_target.py <<'PY'
import socket, threading
IP="10.10.10.5"
def bsrv(port,banner):
    s=socket.socket();s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);s.bind((IP,port));s.listen(50)
    def h(c):
        try:c.sendall(banner.encode());c.settimeout(5);c.recv(1024)
        except Exception:pass
        finally:c.close()
    while True:
        c,_=s.accept();threading.Thread(target=h,args=(c,),daemon=True).start()
def hsrv(port,server):
    s=socket.socket();s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);s.bind((IP,port));s.listen(50)
    body="<html><head><title>Asir Municipality Intranet</title></head><body>Staff portal</body></html>"
    def h(c):
        try:
            c.settimeout(5);c.recv(2048)
            c.sendall(("HTTP/1.1 200 OK\r\nServer: %s\r\nContent-Type: text/html\r\nContent-Length: %d\r\nConnection: close\r\n\r\n%s"%(server,len(body),body)).encode())
        except Exception:pass
        finally:c.close()
    while True:
        c,_=s.accept();threading.Thread(target=h,args=(c,),daemon=True).start()
for f,p,b in [(bsrv,21,"220 (vsFTPd 2.3.4)\r\n"),(bsrv,22,"SSH-2.0-OpenSSH_7.2p2 Ubuntu-4ubuntu2.8\r\n"),(hsrv,80,"Apache/2.4.18 (Ubuntu)"),(hsrv,8080,"Apache-Coyote/1.1")]:
    threading.Thread(target=f,args=(p,b),daemon=True).start()
threading.Event().wait()
PY
cat > /etc/systemd/system/lab-target.service <<'U'
[Unit]
Description=Lab fake target 10.10.10.5
After=network.target
[Service]
ExecStartPre=-/sbin/ip link add lab0 type dummy
ExecStartPre=-/sbin/ip addr add 10.10.10.5/24 dev lab0
ExecStartPre=/sbin/ip link set lab0 up
ExecStart=/usr/bin/python3 /opt/lab/fake_target.py
Restart=always
[Install]
WantedBy=multi-user.target
U

# مستخدمو المجموعات + طرفياتهم (ttyd قاعدته تتضمّن بادئة الوصول)
for i in 1 2 3 4 5 6; do u=g$i
  id $u >/dev/null 2>&1 || useradd -m -s /bin/bash $u; passwd -l $u >/dev/null 2>&1
  printf 'export PS1="\\[\\e[1;32m\\]group-%s\\[\\e[0m\\]:\\w$ "\ncd ~ 2>/dev/null\nalias nmap="nmap -n"\n' $i > /home/$u/.bashrc
  printf 'set -g mouse on\nset -g status off\n' > /home/$u/.tmux.conf
  chown -R $u:$u /home/$u; chmod 700 /home/$u
  cat > /etc/systemd/system/lab-term-$u.service <<U
[Unit]
After=network.target
[Service]
User=$u
Environment=HOME=/home/$u
WorkingDirectory=/home/$u
ExecStart=/usr/bin/ttyd -p 768$i -i lo -b /$ACCESS/t/$u -W -t fontSize=12 -t 'theme={"background":"#0f1b17","foreground":"#aef5c6"}' tmux new-session -A -s lab
Restart=always
RestartSec=2
MemoryMax=300M
[Install]
WantedBy=multi-user.target
U
done


# عزل sshd عن عنوان الهدف ليظهر إصدار الهدف الوهمي لا الحقيقي
mkdir -p /etc/ssh/sshd_config.d
printf 'ListenAddress %s\nListenAddress 127.0.0.1\n' "$IP" > /etc/ssh/sshd_config.d/lab-listen.conf
systemctl restart ssh 2>/dev/null || systemctl restart sshd 2>/dev/null || true

# المنصة
mkdir -p /var/www/cyberlab
cat > /tmp/lab.b64 <<'B64'

B64
base64 -d /tmp/lab.b64 > /var/www/cyberlab/lab.html
LOG "lab.html bytes: $(wc -c </var/www/cyberlab/lab.html)"

# nginx — كل شيء تحت /$ACCESS/ فقط، وما سواه 404
{
echo 'server {'
echo "  listen ${IP}:80 default_server;"
echo '  listen 127.0.0.1:80;'
echo "  server_name $DOMAIN;"
echo '  location = / { return 404; }'
for i in 1 2 3 4 5 6; do
cat <<N
  location /$ACCESS/t/g$i/ { proxy_pass http://127.0.0.1:768$i; proxy_http_version 1.1; proxy_set_header Upgrade \$http_upgrade; proxy_set_header Connection "upgrade"; proxy_set_header Host \$host; proxy_read_timeout 3600s; }
N
done
cat <<N
  location /$ACCESS/ { alias /var/www/cyberlab/; index lab.html; try_files \$uri \$uri/ /$ACCESS/lab.html; }
}
N
} > /etc/nginx/sites-available/cyberlab
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/cyberlab /etc/nginx/sites-enabled/cyberlab
nginx -t 2>&1 | sed 's/^/nginx-test: /'

# جدار: مستخدمو المجموعات لا يصلون إلا للهدف
grep -q "10.10.10.5" /etc/hosts || echo "10.10.10.5 asir-intranet" >> /etc/hosts
for i in 1 2 3 4 5 6; do uid=$(id -u g$i)
  iptables -C OUTPUT -m owner --uid-owner $uid -o lo -j ACCEPT 2>/dev/null || iptables -A OUTPUT -m owner --uid-owner $uid -o lo -j ACCEPT
  iptables -C OUTPUT -m owner --uid-owner $uid -d 10.10.10.0/24 -j ACCEPT 2>/dev/null || iptables -A OUTPUT -m owner --uid-owner $uid -d 10.10.10.0/24 -j ACCEPT
  iptables -C OUTPUT -m owner --uid-owner $uid -j REJECT 2>/dev/null || iptables -A OUTPUT -m owner --uid-owner $uid -j REJECT
done
mkdir -p /etc/iptables; iptables-save > /etc/iptables/rules.v4
printf '[Unit]\nAfter=network.target\n[Service]\nType=oneshot\nExecStart=/sbin/iptables-restore /etc/iptables/rules.v4\nRemainAfterExit=yes\n[Install]\nWantedBy=multi-user.target\n' > /etc/systemd/system/lab-fw.service

systemctl daemon-reload
systemctl enable --now lab-target lab-fw >/dev/null 2>&1
systemctl restart lab-target
for i in 1 2 3 4 5 6; do systemctl enable lab-term-g$i >/dev/null 2>&1; systemctl restart lab-term-g$i; runuser -u g$i -- tmux kill-server 2>/dev/null; done
systemctl enable nginx >/dev/null 2>&1; systemctl restart nginx
sleep 10

# فحص ذاتي

# ضمان إقلاع كل الطرفيات (g1 فشلت أحياناً عند الإقلاع المتزامن)
for pass in 1 2; do for i in 1 2 3 4 5 6; do systemctl is-active --quiet lab-term-g$i || { runuser -u g$i -- tmux kill-server 2>/dev/null; systemctl restart lab-term-g$i; }; done; sleep 3; done

LOG "services: $(for s in nginx lab-target lab-fw lab-term-g1 lab-term-g6; do printf '%s=%s ' $s $(systemctl is-active $s); done)"
LOG "platform: $(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1/$ACCESS/lab.html)"
LOG "term g1: $(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1/$ACCESS/t/g1/)"
LOG "deny /: $(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1/)"
LOG "target scan:"; runuser -u g1 -- nmap -n -sV -p21,22,80,8080 10.10.10.5 2>&1 | grep -E "open|done"

# --- HTTPS عبر certbot + nginx ---
apt-get install -y -qq certbot python3-certbot-nginx >/dev/null 2>&1
certbot --nginx -d "$DOMAIN" --non-interactive --agree-tos -m alhakamik@gmail.com --redirect >/tmp/certbot.log 2>&1
LOG "certbot: $(grep -iE "Congratulations|Successfully|error|failed|unable" /tmp/certbot.log | head -3 | tr '\n' ' ')"
systemctl reload nginx 2>/dev/null
LOG "https: $(curl -s -o /dev/null -w '%{http_code}' --max-time 15 https://$DOMAIN/$ACCESS/lab.html)"

LOG "mem: $(free -m | awk '/Mem/{print $3"MB/"$2"MB"}')"
echo ""
echo "######################################################"
echo "#   LAB URL (HTTPS):  https://$DOMAIN/$ACCESS/"
echo "#   (http fallback):  http://$IP/$ACCESS/"
echo "#   ACCESS :  $ACCESS"
echo "######################################################"
LOG "=== boot done ==="
